    "help.raid.overview.title": "Три стороны, одна встреча",
    "help.raid.overview.body": "Левые, центристские и правые группы сражаются с одним общим боссом. Победите босса этой главы, чтобы попробовать свои собственные группы. Каждый из них нуждается в трех разных героях и должен быть свободен от экспедиций и исследований.<br><br>Оборудование, навыки, формирование и тактика копируются при развертывании. Исцеление, баффы и ауры остаются в их группы. Разногласия по поводу общего босса приносят пользу всем. Выжившие группы продолжают сражаться, если другой падает.",
    "help.raid.patterns.title": "Предупреждения и брейки",
    "help.raid.patterns.body": "Предупреждения показывают атаку, целевые стороны и время удара с соответствующими границами полосы. Хаммер отдает приоритет целевому рангу фронта. Ущелья и волны бьют по всем в их целевых полосах. Знаки и насмешки применяются в пределах выбранной полосы.<br><br>Решение реальных повреждений HP заполняет брусок тяжелой атаки. Разрушение актерского состава разоблачает босса; неудача вызывает сильный удар по всей территории рейда. Нижний босс HP запускает более быстрые и сильные фазы. Сценарные узоры не отменяются обычным действием оглушения.",
    "help.raid.trial.title": "Боевое испытание",
    "help.raid.trial.body": "Это боевое испытание без наград. Тренировочные группы предоставляют девять образцов героев для всех, кто хочет попробовать. Ваши группы также сражаются в качестве моментальных снимков, не потребляя и не меняя героев, снаряжение, инвентарь или прогресс. Позиции не используются.<br><br>Испытание приостанавливается, когда вы покидаете вкладку или скрываете окно. Возвращение возобновляет его; обновление сбрасывает его. Обзор повреждений, исцеления, выживших и перерывов в результатах и повторных попыток. Живые награды, повторяющиеся правила и дополнительные монстры остаются нерешенными.",
