    "hint.forge_up": "Выберите оборудование для модернизации. Проанализируйте изменения следующего шага и необходимые материалы. На низких уровнях неудача тратит только стоимость; на средних уровнях она может уронить элемент на один уровень; на высоких уровнях предмет может сломаться. Разбитый предмет оставляет те же материалы, что и его спасение. Более высокие оценки имеют более низкие шансы на успех, а некоторые успехи — это большие успехи, которые повышают больше.",
