    "ng.attr.cha": "Исцеление · Сокращение ослаблений",
    "ng.note": "Ваша первая группа - <b> 1 Редкий + 1 Магия + 1 Нормальный </b> - список показывает свои <b> уровня </b> с первого экрана. 15 Uniques являются фиксированным списком и не расходуются в начале.<br>Атрибуты качаются по оси, но их <b> суммарно приземляется в полосе его ярусных наборов </b> (ярусные полосы <b> могут перекрываться </b>) — три отличаются по количеству и по форме <b> </b>: Редкий и нормальный крен равномерно, Magic может <b> шип на одной оси </b>. Ни передача, ни подъемы уровня не поднимают их, поэтому то, что вы катите здесь <b>, длится вечно </b>.<br><b> Разрыв ярусов длится до конца </b> — шапка разделяется каждым героем, но выравнивания никогда не поднимают атрибуты, поэтому <b> форма, которую вы катите, - это то, где этот герой заканчивается </b>.<br>Главный грех решает овладение грехом (таб 1) и диспетчерская способность — сродство снаряжения (установочные точки) <b>, сброшенное </b> — перешло к партийной тактике.<br>Перезапуск <b> безлимитный и бесплатный </b> - выбор открытия не является азартной игрой<br><b> Открытый </b>: полосы ярусов, разбросанные формы и весы внешнего вида (все предлагаемые значения) · эффекты признаков (закручены только имена) · насколько сильно класс должен смещать свой ключевой атрибут · разрешены ли дублирующиеся грехи / классы",
