    "pro.skip": "Пропустить",
    "pro.begin": "Начать",
    "pro.s1.h": "Трон",
    "pro.s1.b": "У ада был царь. Имя ему было Баал, архидемон.\n\nВ этих землях всё принадлежало ему.\nБаал разделил между слугами семь своих страстей.\nГнев, зависть, алчность, лень, чревоугодие, похоть и гордыню.\n\nУ подножия трона семеро слуг ждали его приказа.",
    "pro.s2.h": "Ночь предательства",
    "pro.s2.b": "Однажды особенно тёмной ночью семь клинков вонзились Баалу в спину.\n\nОн обернулся и увидел знакомые лица.\nПопытался дать отпор, но силы у него уже отняли.\n\nКто-то передал им ключ. Баала оттеснили назад. Земля ушла из-под ног.\nТрон, глядящие сверху лица, багровый свет ада — всё удалялось в вышине.",
    "pro.s3.h": "Падение",
    "pro.s3.b": "Лица, которые он успел разглядеть, меркли одно за другим.\nДействительно ли клинков было семь? Он уже не знал.\n\nБоль жгла плоть. На его теле выжигали клеймо.\n\nЧтобы вновь вступить в бой, ему нужны те, кто возьмётся за оружие по его приказу.\n\n<em>Я найду тех, кто вонзил клинки мне в спину. Одного за другим.</em>",
    "pro.s4.h": "Деревня",
    "pro.s4.b": "Он открыл глаза. Старик-человек по капле вливал ему в рот воду.\nСтав человеком, Баал даже не мог сам поднять голову.\n\nНесколько дней жители деревни отламывали куски от своего хлеба, чтобы накормить его.\n\n<em>Зачем этим созданиям сохранять мне жизнь?</em>",
    "pro.s5.h": "Пламя",
    "pro.s5.b": "Над деревней взметнулось пламя. Пришло войско Сатаны.\nТот, кого Баал изгнал из ада, выследил его даже здесь.\n\nБаал поднял руку, обращаясь к наёмникам, которых собрал в деревне.",
    "pro.s5.q": "«Расчистите путь. Мы идём за Сатаной».",
    "pro.end": "Глава 1. Гнев / Пылающее поле боя",
