    "exp.repeat.tip": "On: loop through this area's stages · Off: перейдите на следующий этап после каждой победы",
    "exp.repeat.sub": "Экспедиции <b> никогда не останавливаются сами по себе </b> — когда запускается следующая, выходит в ближайшее время; только <b> Retreat </b> или <b> закрытие игры </b> останавливает их • они запускаются <b> только во время открытия игры </b><br>Выигрыш переходит к следующему этапу · проигрыш (целая группа сбита · вычеркнута) снова проходит тот же этап · проигрыш боссу главы возвращается к предыдущему этапу · <b> с повторением на </b> сторона проходит через этапы области I → II → III → I; <b> с ним от </b> он переходит к следующему этапу в порядке (тот же этап снова, если следующий заблокирован · избиение босса, который разблокирует следующую сложность переходит к этой сложности 1-1) · каждый этап является новым пробегом, поэтому все отправляются восстановленные",
