    "mm.tut": "Обучение",
    "mm.tut.c1_depart.tab": "Экспедиции отправляют вашу группу в бой. Сражения разыгрываются сами по себе, а снаряжение и материалы, которые они находят, накапливаются в вашем инвентаре.",
    "mm.tut.c1_depart.place": "Выберите область для борьбы. Выиграйте этап, чтобы перейти к следующему. Начальник участка ждет на заключительном этапе.",
    "mm.tut.c1_depart.send": "После развертывания ваш отряд автоматически сражается. Экспедиции продолжаются, пока игра открыта. Лаборатория продолжает работать, пока вас нет.",
    "mm.tut.c1_storage.tab": "Потратьте золото в строительстве, чтобы построить объекты и открыть новые возможности.",
    "mm.tut.c1_storage.lot": "Выберите здание, чтобы увидеть его разблокировки в панели справа. Строительный склад открывает линию ресурсов лаборатории.",
    "mm.tut.c1_storage.build": "Building Storage открывает линию ресурсов лаборатории, которая продолжает собирать материалы даже в то время, когда игра закрыта. Оплатите стоимость, и она будет построена сразу.",
    "mm.tut.c1_reg.tab": "Лаборатория продолжает работать, пока игра закрыта. Назначьте хотя бы одного героя на каждую строчку, которую вы хотите запустить.",
    "mm.tut.c1_reg.line": "Нажмите на пустой слот, чтобы выбрать героя для линии Ресурсов.",
    "mm.tut.c1_reg.hero": "Назначенные герои еще могут отправляться в экспедиции. Каждый герой на линии Ресурсов помогает быстрее собирать материалы.",
    "mm.tut.c1_reg.apply": "Выберите [Применить], чтобы назначить героя и начать производство. Материалы, собранные во время вашего отсутствия, будут в наличии, когда вы вернетесь.",
