    "nt.retry.detail": "Группа {party} · {stage} · {n} недавних пробегов без ясности. Просмотрите снаряжение, мастерство и зелья или разработайте более раннюю стадию.",
    "ch.salvageHint": "Нажмите правой кнопкой мыши и нажмите [Заблокировать], чтобы заблокировать или разблокировать его. Запертое снаряжение никогда не спасается. Нажмите [Salvage], чтобы открыть Коробку Спасения: щелкните передачу, чтобы положить ее или выберите из редкости, уровня и базовых столбцов, и соответствующая передача входит сразу — [Salvage Now] превращает ее в пыль и очищает пики. С несколькими выбранными колоннами, только передача, соответствующая каждой колонке, входит, так что вы можете поддерживать высокую базовую опцию с базовой колонкой. [Автоспасение] устанавливается за группу. Для каждой редкости × слот ячейки выберите Keep, Base или Salvage и включите условие уровня, чтобы спасти снаряжение намного ниже самого низкого уровня героя группы. Гир хранится только тогда, когда он соответствует как состоянию уровня, так и его ячейке; базовая ячейка сохраняет только передачу, базовая опция которой находится на пороге или выше этого слота. Уникальные и изготовленные экипировки всегда хранятся. Проверяется только новое снаряжение — нажмите [Применить инвентарь сейчас], чтобы спасти то, что у вас уже есть. Сохраните правила в предустановленном виде, чтобы загрузить их на другую сторону",
