    "cs.last.open": "Последний вызов: {result} · {sec} с · Пол {n} разблокирован",
    "cs.help": "Начните с первого этажа Башни испытаний. Победа на верхнем из открытых этажей открывает следующий. Поражение не сбрасывает прогресс, а на пройденные этажи можно вернуться.<br>На каждом этаже состав противников постоянен. Сначала вас ждут элитные отряды и боссы этапов, затем отряд соперников и босс главы. Номер этажа задаёт базовый уровень врага.",
    "nav.arena": "Арена",
    "nav.tagMatch": "Колизей",
    "hint.tagMatch": "Зарегистрируйте три отряда в порядке защиты. В атаке изучите ряды, лидеров, умения и тактические карты соперника, затем расставьте отряды. Побеждает сторона, первой выигравшая два раунда. Иначе после трёх раундов объявляется ничья.",
