    "ar.ratingFlash": "Рейтинг {after} ({delta})",
    "ar.last.rated": "Последний поединок: {result} · Рейтинг {after} ({delta})",
    "ar.rules": "Правила дуэли",
    "ar.help.rating": "Арена оценивается по рейтингу. Выигрыши поднимают его, а потери понижают; избиение более сильных противников выигрывает больше, а проигрыш им стоит меньше. Переступить порог, чтобы подняться в лигу.<br>Противники распределены ниже, вблизи и выше вашего рейтинга. +/- на каждой карте - это то, насколько ваш рейтинг меняется, если вы выигрываете или проигрываете. Новые соперники появляются после каждого поединка.<br>Ваш рейтинг устанавливается в момент начала поединка — закрытие повтора не меняет результата. Оппоненты - это группы защиты, зарегистрированные другими игроками.",
    "ar.select": "Члены команды {n} / 3",
    "ar.edit": "Группа по монтажу",
    "ar.needTeam": "Назначение {n} героев",
    "ar.empty": "Пустой слот",
    "ar.noOpponent": "Выберите противника, чтобы раскрыть свою команду",
    "ar.noTactic": "Никаких тактических карт",
    "ar.fight": "Начать дуэль",
    "ar.back": "Вернуться в Арена",
    "ar.draw": "рисовать",
    "ar.last": "Последний поединок: {result} · {sec} с",
    "ar.help": "Выберите сохраненную группу, чтобы использовать ее героев и передние или задние ряды. Редактировать членов и формирование на партийной вкладке. Назначьте трех героев, чтобы начать поединок.<br>Один раунд использует индивидуальную статистику, снаряжение и навыки, а также тактику и зелья выбранной стороны и бонусы Кодекса. Противники используют собственную тактику и зелья. Достижение срока заканчивается вничью.<br>Дуэли проходят независимо от экспедиций, без наград, кодексов и затрат на ресурсы. Пьяные напитки не берутся из вашего запаса. Ваш рейтинг Arena и прогресс Tower of Trials сохранены; выбранный противник и последний результат сбрасываются при перезагрузке.",
