    "dp.help": "Линии производят со временем <b> только с героем, назначенным </b> — даже в то время как игра закрыта (до {h} ч · Поиск до заполнения слотов)<br>Выберите узел и <b> Research </b>, чтобы поднять его уровень — требуется время, и лаборатория работает <b> по одному за раз </b> · отмена возврата полной стоимости · Лабораторный ранг открывает новые узлы<br>Каждый герой <b> присвоил </b> Ресурсам или Игровому Дену производит <b> одну акцию </b> (1 герой 100% · 2 200% · 3 300%), каждый герой в Поиске запускает <b> собственных часов </b>, а статистика добавляет бонус сверху — Удачный джекпот · Время исследования интеллекта · Качество Харизмы · Освоение Жизни (более длительное назначение) · Лидерство сверстников на линии · Стоимость исследований гибкости. Назначение не останавливает экспедиции или исследования.<br>Линия <b> Training </b> дает XP своим назначенным героям (до верхнего уровня списка) · Линия <b> Gambling Den </b> открывается вместе с игровым логово Tavern's Gambling Den",
