    "gb.help": "Таверна открывает его. Нет предела вращения — вращение до тех пор, пока вы можете заплатить ставку. Спин × {n} играет {n} спинов сразу и останавливается рано, если у вас закончилось золото<br>Золото и спин: три соответствующих символа на любой из {lines} строк или диагонали платят золото или материалы. Уайлдс стоят за другими символами; монеты ломают линию<br>Land {trig} + монеты для Hold & Spin — монеты склеиваются, и каждая новая монета сбрасывает спины до {re}. Заполните доску для Grand<br>Ставки следуют вашей текущей главе. Более высокие ставки разблокируются с рангами Таверны. Никакое оборудование или стигма не выходят",
