    "tc.name.duel": "Поединок",
    "tc.name.wedge": "Клин",
    "tc.name.trojan": "Троянский конь",
    "tc.name.charge": "Рыцарский натиск",
    "tc.name.shieldwall": "Стена щитов",
    "tc.name.guard": "Королевская гвардия",
    "tc.name.turtle": "Черепаха",
    "tc.name.retreat": "Ложное отступление",
    "tc.name.poison_arrow": "Отравленная стрела",
    "tc.name.fire_arrow": "Огненная стрела",
    "tc.name.guardian": "Страж",
    "tc.desc.guardian": "Если ваш лидер — единственный живой союзный герой в переднем ряду, союзники в заднем ряду получают на {p1} меньше урона.",
    "tc.name.unity": "Единый фронт",
    "tc.desc.unity": "Пока в живых хотя бы {p2} союзных героев, прямой урон союзных героев увеличен на {p1}.",
    "tc.name.dying_curse": "Предсмертное проклятие",
    "tc.desc.dying_curse": "Когда погибает союзный герой, положительные значения защиты и сопротивлений стихиям у врагов снижаются на {p1} от текущих. До {p2} раз за раунд.",
    "tc.name.giant": "Гигант",
    "tc.name.desperate_charge": "Отчаянный натиск",
    "tc.name.mutual_cover": "Щитовой строй",
    "tc.desc.mutual_cover": "Если разместить двоих героев впереди и одного сзади, каждый герой переднего ряда принимает на себя {p1} урона, который получил бы его напарник.",
    "tc.name.open_order": "Рассредоточение",
    "tc.name.iron_line": "Последний рубеж",
    "tc.desc.iron_line": "Если все герои изначально стоят в переднем ряду, первый союзник, получивший смертельный урон, выживает с 1 ОЗ. Один раз за бой.",
    "tc.name.pursuit": "Преследование",
    "tc.desc.pursuit": "Если все герои изначально стоят впереди, атаки по одной цели предпочитают доступного врага с наименьшей долей оставшегося здоровья.",
    "tc.name.hammer_anvil": "Строй «Крылья журавля»",
    "tc.desc.hammer_anvil": "Если разместить двоих героев впереди и одного сзади, противники заднего ряда делят между собой {p1} урона, который получил бы противник переднего ряда.",
    "tc.name.field_medics": "Полевые медики",
    "tc.desc.field_medics": "При расстановке двое впереди и один сзади передние герои получают на {p1} больше лечения.",
    "tc.name.vanguard_barrier": "Оплот авангарда",
    "tc.desc.vanguard_barrier": "При расстановке один впереди и двое сзади передний герой в начале каждого раунда получает барьер на {p1} своего максимального здоровья.",
    "tc.name.aimed_fire": "Точный огонь",
    "tc.desc.aimed_fire": "При расстановке один впереди и двое сзади задние герои получают +{p1} к шансу критического попадания при атаке по одной цели.",
    "tc.name.volley": "Сосредоточенный огонь",
    "tc.desc.volley": "Если все герои изначально стоят в заднем ряду, ваша сторона наносит на {p1} больше урона противникам переднего ряда.",
    "tc.name.rapid_deployment": "Быстрое развёртывание",
    "tc.desc.rapid_deployment": "Если все герои изначально стоят сзади, в начале каждого раунда шкала действия каждого героя заполняется на {p1}.",
    "tc.desc.open_order": "Если все герои изначально стоят в заднем ряду, ваша сторона получает на {p1} меньше урона от атак по площади.",
    "tc.desc.desperate_charge": "Если все ваши герои изначально стоят в переднем ряду, ваша сторона наносит врагам на {p1} больше урона весь бой.",
    "tc.desc.giant": "Пока в живых ровно один союзный герой, все семь его базовых характеристик повышены на {p1}.",
    "tc.name.baggage": "Обоз",
    "tc.desc.duel": "Одиночные атаки командира нацелены только на вражеского командира. После его гибели цели выбираются как обычно.",
    "tc.desc.wedge": "Одиночная атака командира помечает поражённого врага на {p1} с. Одиночные атаки союзников в первую очередь нацелены на отмеченного врага.",
    "tc.desc.trojan": "Ваш задний ряд бездействует первые {p1} с раунда. Затем его одиночные атаки нацеливаются на вражеский задний ряд.",
    "tc.desc.charge": "В начале раунда ваш передний ряд действует сразу. Первое действие заднего ряда задерживается на {p1} с.",
    "tc.desc.shieldwall": "Живые союзники переднего ряда делят между собой {p1} прямого урона, предназначенного вашему заднему ряду.",
    "tc.desc.guard": "Союзник с наибольшим текущим запасом здоровья принимает на себя {p1} прямого урона от одиночных атак по вашему командиру.",
    "tc.desc.turtle": "В первые {p1} с раунда получаемый отрядом урон снижается на {p2}, а скорость атаки — на {p3}.",
    "tc.desc.retreat": "Когда здоровье бойца переднего ряда впервые за раунд падает ниже {p1}, он ищет союзника заднего ряда с наибольшей долей оставшегося здоровья. Если у того доля выше, они меняются местами до конца раунда.",
    "tc.desc.poison_arrow": "Преобразует {p1} физического урона отряда в урон ядом.",
    "tc.desc.fire_arrow": "Преобразует {p1} физического урона отряда в огненный. С вероятностью {p2} накладывает ожог.",
    "tc.desc.baggage": "Когда союзник выпивает зелье, остальные живые союзники делят между собой исцеление в размере {p1} от его эффекта.",
