    "sk.cool": "Охлаждение {s} с",
    "sk.cdrShort": "Сокращение Cooldown",
    "sk.slots.note": "Когда приходит ваша очередь: <b> самый долгожданный готовый навык </b> → связки идут к <b> слот-заказу </b> → ни один готовый не означает базовую атаку. <b> Магическое оружие не имеет базовой атаки </b> — ничего не готово, калибр ждет полный и отбрасывает момент, когда навык готов<br>Одно действие за поворот. Навык <b> заменяет </b>, который поворачивает атаку, и нет маны — само действие является единственной ценой.<br>Cooldowns работает в режиме реального времени<br>Базовые атаки — это всегда <b> физический </b> — только навыки наносят элементарный урон.<br>Навыки принадлежат к классу <b> </b> - каждый навык находится в одном классе; слот героя рисует из <b> пул класса героя </b> и выученный слот из <b> книги, которую вы читаете </b>. <b> Нападение, исцеление и вызов </b> навыков нуждаются в оружии класса этого навыка в любом слоте; <b> буффов и отрывков </b>, таких как крики, ауры и благословения работают с любым оружием<br>Названия и формы установлены, но <b> мультипликаторов, хитов, охлаждений и продолжительности не опубликованы </b> - текущие номера являются заполнителями.",
