    "sk.sinTree.sub": "Все герои {sin}",
    "sk.sinTree.missing": "<b> Нижний ряд (реактивный) имеет направление, но не имеет чисел </b> — «когда X, тогда Y» масштабируется с триггерной частотой, и для этого пока нет критерия.",
    "sk.mastery": "{cls} Мастерство",
    "sk.mastery.missing": "Классовое мастерство использует <b> ту же структуру </b>, что и греховное мастерство. <b> Каждый класс имеет три подтвержденных узла в верхнем ряду. </b><br><b> Оборудованное снаряжение активирует три узла ниже. </b> Быстрое оружие активирует Повреждение %, медленное оружие активирует Скорость атаки, а тип брони класса активирует Armor Mastery. Вы можете инвестировать ранги без соответствующего оборудования, но эффект остается неактивным.<br>Реактивный нижний ряд все еще разрабатывается.",
