    "sk.adv.band.common": "Общее мастерство",
    "sk.advTree.missing": "Изучите один из трех основных навыков пути для <b>, один общий пункт </b>. Очки приходят со всеми уровнями из Lv1 и делятся с мастерством Sin и Class.<br>Основные разряды Lv1-5 разблокировать у героя Lv30/35/40/45/50. Специальные, Variant и Ultimate филиалы появятся позже.",
    "sk.lockedSuffix": " (заперта)",
    "sk.grid.note": "Мастерство — это не ветвящееся дерево, а <b> стек сверху вниз </b> — <b> верхний ряд открывается первым, нижние ряды позже </b><br>Нажмите на ячейку, чтобы добавить ранг. Ячейки, которые вы не можете открыть, пока показывают <b> уровень, который им нужен </b>. <b> Пустые ячейки являются неписаным дизайном </b>; пунктирная рама остается, чтобы вы могли видеть, как далеко это может зайти",
