    "tv.sub": "Редкий уровень — класс × грех × черта, прокатанная по прибытии",
    "tv.reroll.note": "Рероллы в тавернах — это <b> предметное земледелие для героев </b> — катящаяся петля живет в <b> редком ярусе </b>, который снабжает все комбинации 35 sin × class.",
    "tv.tiers.note": "<b> Unique </b> — фиксированное имя, класс и грех + 1 навык подписи (герой-эксклюзив); одна копия на реестр. В базовой игре 15 человек (3 в классе)<br><b> Rare </b> — все свернуто; мастерство подписи закреплено из общего пула. Охватывает все 35 клеток класса sin ×",
