    "cx.note": "Каждый раз, когда кодекс EXP, собранный у монстра, проходит кумулятивный порог, <b> его уровень кодекса </b> поднимается и открывает еще один бонусный эффект — ранние (убей EXP · повреди его · шанс падения) применяют <b> к этому монстру только </b> • последний добавляет <b>, что боевой вариант монстра для всей вашего отряда </b> навсегда — <b> фермерство толкает кодекс </b><br>Кодек каждого убийства EXP определяется сложностью экспедиции — более высокие трудности заполняют его быстрее • только убивает от раундов, которые вы выигрываете счет · масштабирование уровня босса приходит позже<br>Наведите на карту, чтобы увидеть историю монстра и вехи уровня",
