    "bt.note": "Наблюдение разрешено, но <b> никогда не требуется </b> — скорость только меняет темп. Изменения в груше и деревце навыков во время пробежки применяются <b> сразу </b>, в том числе во время боёв с боссами · каждый раунд <b> окупается в тот момент, когда вы выигрываете его </b> (сумка · золото · XP · кодекс).<br><b> Retreat </b> останавливает экспедицию — она бросает раунд в ход и сохраняет то, что дали выигранные раунды; нажимает, пока следующий забег отсчитывает, следующий забег не выходит. Закрытие игры отрезает экспедицию на месте.",
