    "타격의 일부가 고정 피해로\tPart of each hit becomes fixed damage": "Часть каждого удара становится фиксированным повреждением.",
    "모으기 속도\tCharge speed": "Скорость зарядки",
    "체력이 가득 찬 적에게 주는 첫 타격 데미지\tFirst-hit damage to full-HP enemies": "Ущерб, нанесенный первым ударом врагам ПНВ",
    "평타가 한 발 더 나갈 확률\tChance for an extra basic attack": "Шанс для дополнительной базовой атаки",
    "파티의 평타 덤 데미지\tParty on-hit effect damage": "Повреждение от удара по группы",
    "적이 쓰러질 때마다 파티 공격 속도(3초)\tParty Attack Speed for 3s on each kill": "Партийная скорость атаки по 3 на каждое убийство",
    "내 회복량\tHealing done": "Исцеление завершено",
