    "총합이 낮은 대역 · 분포가 넓어 한 축이 크게 튈 수 있음\tLower stat total · a wide spread so one axis can spike": "Нижняя общая статистика · широкий разброс, так что одна ось может колебаться",
    "총합이 높은 대역 · 정규분포라 극값이 드물고 고르게 분포\tHigher stat total · a normal spread so extremes are rare": "Более высокий общий показатель; нормальное распространение, поэтому крайности редки",
    "이름·직업·죄종 고정 + 고유 스킬 1개(영웅 전용) · 영웅 로스터에 1명만\tFixed name class & sin + 1 signature skill (hero-exclusive) · one per roster": "Класс фиксированных имен & sin + 1 навык подписи (герой-эксклюзив) · по одному на список",
    "총합이 가장 낮은 대역 · 정규분포라 고르게 분포\tLowest stat total · a normal spread so stats come out even": "Самый низкий общий показатель; нормальное распространение, поэтому статистика выходит даже",
    "고블린 전용 등급 · 모든 능력치가 낮게 시작 · 레벨마다 능력치 하나 성장\tGoblin-only grade · every stat starts low · one stat grows each level": "Сорт только для гоблина · каждый показатель начинает с низкого уровня · один показатель растет на каждом уровне",
